#!/usr/bin/env python3
"""Original A3 tracker, initial draft generated by Codex, 2026-11-15.

Standard-library local SQLite store. No network access, shells, or email sends.
SQLite API contract: https://docs.python.org/3/library/sqlite3.html
"""
from __future__ import annotations
import argparse
from contextlib import contextmanager
from datetime import datetime, timezone, timedelta
import hashlib
import json
import math
import os
from pathlib import Path
import re
import sqlite3
import sys
import uuid


class Conflict(ValueError):
    pass


def instant(value):
    if not isinstance(value, str) or len(value) > 64:
        raise ValueError("due must be an ISO datetime with timezone")
    try:
        result = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        raise ValueError("due must be an ISO datetime with timezone") from None
    if result.utcoffset() is None:
        raise ValueError("due must include an explicit timezone")
    return result.astimezone(timezone.utc)


def text(value, name, limit, empty=False):
    if (not isinstance(value, str) or len(value) > limit or (not empty and not value.strip())
            or any(ord(c) < 32 or ord(c) == 127 for c in value)):
        raise ValueError("invalid " + name)
    return value.strip()


def number(value, name, minimum, maximum):
    if type(value) not in (float, int) or not math.isfinite(value) or not minimum <= value <= maximum:
        raise ValueError("invalid " + name)
    return value


def fields(data, allowed, required=()):
    if not isinstance(data, dict) or set(data) - set(allowed) or set(required) - set(data):
        raise ValueError("invalid or missing fields")


def identifier(value):
    if not isinstance(value, str) or not re.fullmatch(r"[a-f0-9]{32}", value):
        raise ValueError("invalid assignment id")
    return value


class Tracker:
    def __init__(self, path, clock=lambda: datetime.now(timezone.utc)):
        self.path, self.clock = Path(path).absolute(), clock
        self.path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        # Resolve parent aliases, but never follow a database-file symlink.
        if self.path.is_symlink() or (self.path.exists() and not self.path.is_file()):
            raise ValueError("database must be a regular local file")
        # umask is set by CLI; reserve new files privately even for library callers.
        try:
            fd = os.open(self.path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            os.close(fd)
        except FileExistsError:
            pass
        self.db = sqlite3.connect(self.path, timeout=15, isolation_level=None)
        self.db.row_factory = sqlite3.Row
        self.db.execute("PRAGMA busy_timeout=15000")
        self.db.execute("PRAGMA foreign_keys=ON")
        self.db.execute("PRAGMA synchronous=FULL")
        with self.transaction():
            version = self.db.execute("PRAGMA user_version").fetchone()[0]
            if version not in (0, 1):
                raise ValueError("unsupported tracker schema")
            self.db.execute("""CREATE TABLE IF NOT EXISTS assignments (
                id TEXT PRIMARY KEY, title TEXT NOT NULL, course TEXT NOT NULL,
                due TEXT NOT NULL, estimated_hours REAL NOT NULL CHECK(estimated_hours BETWEEN 0 AND 10000),
                progress REAL NOT NULL CHECK(progress BETWEEN 0 AND 100),
                note TEXT NOT NULL, archived INTEGER NOT NULL CHECK(archived IN (0,1)),
                revision INTEGER NOT NULL CHECK(revision >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL
            )""")
            self.db.execute("""CREATE TABLE IF NOT EXISTS events (
                sequence INTEGER PRIMARY KEY AUTOINCREMENT,
                assignment_id TEXT NOT NULL REFERENCES assignments(id), revision INTEGER NOT NULL,
                action TEXT NOT NULL, at TEXT NOT NULL, snapshot TEXT NOT NULL,
                UNIQUE(assignment_id, revision))""")
            self.db.execute("""CREATE TABLE IF NOT EXISTS admissions (
                key TEXT PRIMARY KEY, request_hash TEXT NOT NULL,
                assignment_id TEXT NOT NULL REFERENCES assignments(id))""")
            self.db.execute("PRAGMA user_version=1")

    @contextmanager
    def transaction(self):
        self.db.execute("BEGIN IMMEDIATE")
        try:
            yield
            self.db.execute("COMMIT")
        except BaseException:
            self.db.execute("ROLLBACK")
            raise

    def close(self):
        self.db.close()

    def get(self, key):
        row = self.db.execute("SELECT * FROM assignments WHERE id=?", (identifier(key),)).fetchone()
        if row is None:
            raise ValueError("assignment not found")
        result = dict(row)
        result["archived"] = bool(result["archived"])
        return result

    def record(self, key, action):
        row = self.get(key)
        self.db.execute("INSERT INTO events(assignment_id,revision,action,at,snapshot) VALUES(?,?,?,?,?)",
                        (key, row["revision"], action, row["updated_at"], json.dumps(row, sort_keys=True)))
        return row

    def add(self, data):
        fields(data, ("title", "course", "due", "estimated_hours", "idempotency_key"),
               ("title", "course", "due", "estimated_hours"))
        title, course = text(data["title"], "title", 200), text(data["course"], "course", 80)
        due = instant(data["due"]).isoformat()
        hours = number(data["estimated_hours"], "estimated_hours", 0, 10000)
        admission = text(data["idempotency_key"], "idempotency_key", 128) if "idempotency_key" in data else None
        fingerprint = hashlib.sha256(json.dumps([title, course, due, float(hours)]).encode()).hexdigest()
        with self.transaction():
            if admission:
                prior = self.db.execute("SELECT * FROM admissions WHERE key=?", (admission,)).fetchone()
                if prior:
                    if prior["request_hash"] != fingerprint:
                        raise Conflict("idempotency key reused with different assignment")
                    return self.get(prior["assignment_id"])
            key, now = uuid.uuid4().hex, self.clock().astimezone(timezone.utc).isoformat()
            self.db.execute("INSERT INTO assignments VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                            (key, title, course, due, hours, 0, "", 0, 1, now, now))
            if admission:
                self.db.execute("INSERT INTO admissions VALUES(?,?,?)", (admission, fingerprint, key))
            return self.record(key, "created")

    def update(self, data):
        fields(data, ("id", "expected_revision", "title", "course", "due", "estimated_hours", "progress", "note", "archived"),
               ("id", "expected_revision"))
        key = identifier(data["id"])
        revision = data["expected_revision"]
        if type(revision) is not int or revision < 1 or len(data) < 3:
            raise ValueError("valid revision and at least one change required")
        changes = {}
        for name in ("title", "course", "note"):
            if name in data:
                changes[name] = text(data[name], name, {"title": 200, "course": 80, "note": 2000}[name], empty=name == "note")
        if "due" in data:
            changes["due"] = instant(data["due"]).isoformat()
        for name, maximum in (("progress", 100), ("estimated_hours", 10000)):
            if name in data:
                changes[name] = number(data[name], name, 0, maximum)
        if "archived" in data:
            if type(data["archived"]) is not bool:
                raise ValueError("archived must be boolean")
            changes["archived"] = int(data["archived"])
        with self.transaction():
            prior = self.get(key)
            if prior["revision"] != revision:
                raise Conflict("revision conflict; re-read before updating")
            changes["revision"] = revision + 1
            changes["updated_at"] = self.clock().astimezone(timezone.utc).isoformat()
            # Column names come only from the fixed map above; values are bound.
            self.db.execute("UPDATE assignments SET " + ",".join(k + "=?" for k in changes) + " WHERE id=?",
                            (*changes.values(), key))
            return self.record(key, "updated")

    def list(self, data):
        fields(data, ("include_archived",))
        include = data.get("include_archived", False)
        if type(include) is not bool:
            raise ValueError("include_archived must be boolean")
        rows = self.db.execute("SELECT id FROM assignments WHERE archived=0 OR ? ORDER BY due,id", (include,)).fetchall()
        return [self.get(row[0]) for row in rows]

    def history(self, data):
        fields(data, ("id",), ("id",))
        key = self.get(data["id"])["id"]
        return [dict(row) | {"snapshot": json.loads(row["snapshot"])} for row in
                self.db.execute("SELECT * FROM events WHERE assignment_id=? ORDER BY sequence", (key,))]

    def summary(self, data):
        fields(data, ("horizon_days", "daily_hours"))
        horizon = number(data.get("horizon_days", 7), "horizon_days", 0, 365)
        daily = number(data.get("daily_hours", 2), "daily_hours", 0.1, 24)
        now = self.clock().astimezone(timezone.utc)
        result, cumulative = [], 0.0
        for row in self.list({}):
            remaining = row["estimated_hours"] * (1 - row["progress"] / 100)
            due = instant(row["due"])
            if row["progress"] == 100 or due > now + timedelta(days=horizon):
                continue
            cumulative += remaining
            capacity = max(0, (due - now).total_seconds() / 86400) * daily
            result.append(row | {"remaining_hours": round(remaining, 2),
                                "hours_until_due": round((due - now).total_seconds() / 3600, 2),
                                "overdue": due < now, "cumulative_hours_due": round(cumulative, 2),
                                "available_hours_until_due": round(capacity, 2),
                                "capacity_risk": cumulative > capacity})
        return {"as_of": now.isoformat(), "horizon_days": horizon, "daily_hours": daily,
                "capacity_assumption": "continuous days at entered daily budget; no calendar availability inferred",
                "assignments": result, "total_remaining_hours": round(sum(x["remaining_hours"] for x in result), 2)}

    def backup(self, destination):
        dest = Path(destination).absolute()
        if not dest.parent.is_dir() or dest.is_symlink() or dest.exists():
            raise ValueError("backup requires a new file in an existing local directory")
        fd = os.open(dest, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        os.close(fd)
        with sqlite3.connect(dest) as target:
            self.db.backup(target)
            if target.execute("PRAGMA integrity_check").fetchall() != [("ok",)]:
                raise ValueError("backup integrity check failed")
        return {"backup_created": True, "sha256": hashlib.sha256(dest.read_bytes()).hexdigest()}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=("add", "update", "list", "summary", "history", "backup"))
    parser.add_argument("--destination", help="new local backup file (backup only)")
    args = parser.parse_args()
    os.umask(0o077)
    tracker = None
    try:
        raw = sys.stdin.buffer.read(16385)
        if len(raw) > 16384:
            raise ValueError("input too large")
        data = json.loads(raw or b"{}", parse_constant=lambda _: (_ for _ in ()).throw(ValueError("nonfinite JSON")))
        path = os.environ.get("A3_TRACKER_DB") or str(Path(os.environ.get("XDG_DATA_HOME", str(Path.home() / ".local/share"))) /
                    "assignment-deadline-progress-tracker/tracker.sqlite")
        tracker = Tracker(path)
        if args.command == "backup":
            fields(data, ())
            if not args.destination:
                raise ValueError("backup needs --destination")
            result = tracker.backup(args.destination)
        else:
            if args.destination:
                raise ValueError("destination applies only to backup")
            result = getattr(tracker, args.command)(data)
        print(json.dumps({"ok": True, "result": result}, allow_nan=False))
        return 0
    except (ValueError, OSError, sqlite3.Error):
        # Do not echo raw user input, paths, notes, or provider secrets on errors.
        print(json.dumps({"ok": False, "error": "conflict" if isinstance(sys.exception(), Conflict) else "invalid_request_or_storage_failure"}))
        return 2
    finally:
        if tracker:
            tracker.close()


if __name__ == "__main__":
    raise SystemExit(main())
